# ==============================================================
# EXPERIMENT 8 : ECDSA FROM SCRATCH  (curve P-256, SHA-256)
#                only hashlib (SHA-256) and random are used
# ==============================================================
# THEORY:
#   Curve P-256:  y^2 = x^3 + a*x + b  (mod p),  base point G,
#                 n = number of points generated by G (a prime)
#
#   KEYGEN : private d = random number in [1, n-1]
#            public  Q = d * G                    (a point)
#
#   SIGN (message m, private d):
#       z = SHA-256(m) as a number
#       pick random k in [1, n-1]
#       (x1, y1) = k * G
#       r = x1 mod n                              (if r = 0, pick new k)
#       s = k^-1 * (z + r*d) mod n                (if s = 0, pick new k)
#       signature = (r, s)
#
#   VERIFY (message m, signature (r, s), public Q):
#       z  = SHA-256(m) as a number
#       w  = s^-1 mod n
#       u1 = z*w mod n,   u2 = r*w mod n
#       (x1, y1) = u1*G + u2*Q
#       valid  if  x1 mod n == r
#
#   WHY IT WORKS:  u1*G + u2*Q = (z*w + r*w*d)*G = w*(z + r*d)*G = k*G
#
#   NOTE: numbers here are 256 bits long, so the "try every number"
#   inverse and "add P k times" from Exp 3 would take forever.
#   We use:  inverse = pow(a, -1, n)   (Python built-in modular inverse)
#            k * P   = double-and-add  (k in binary)
#   WARNING: never reuse k for two messages - the private key leaks.
# ==============================================================

import hashlib
import random

# ---------------- P-256 curve constants (public, from the standard) ----------------
p = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
a = p - 3
b = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
G = (0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296,
     0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5)
n = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551

rng = random.SystemRandom()         # secure random numbers (from the OS)


# --------------------------------------------------------------
# point_add : P + Q on the curve  (None = point at infinity)
#   same formulas as Exp 3 ECC
# --------------------------------------------------------------
def point_add(P, Q):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and (y1 + y2) % p == 0:             # P + (-P) = infinity
        return None
    if P == Q:
        s = (3 * x1 * x1 + a) * pow(2 * y1, -1, p) % p    # tangent slope
    else:
        s = (y2 - y1) * pow(x2 - x1, -1, p) % p           # line slope
    x3 = (s * s - x1 - x2) % p
    y3 = (s * (x1 - x3) - y1) % p
    return (x3, y3)


# --------------------------------------------------------------
# scalar_mult : k * P by double-and-add
#   look at k in binary: for each bit, if 1 -> add, then double
# --------------------------------------------------------------
def scalar_mult(k, P):
    R = None                        # result starts at infinity ("zero")
    while k > 0:
        if k % 2 == 1:              # lowest bit is 1
            R = point_add(R, P)     # add current power-of-2 multiple
        P = point_add(P, P)         # double: P, 2P, 4P, 8P ...
        k = k // 2                  # next bit
    return R


# --------------------------------------------------------------
# hash_to_int : SHA-256 of the message as a number
# --------------------------------------------------------------
def hash_to_int(message):
    return int.from_bytes(hashlib.sha256(message).digest(), "big")


# --------------------------------------------------------------
# keygen
# --------------------------------------------------------------
def keygen():
    d = rng.randint(1, n - 1)       # private key (a number)
    Q = scalar_mult(d, G)           # public key (a point)
    return d, Q


# --------------------------------------------------------------
# sign : uses the PRIVATE key d
# --------------------------------------------------------------
def sign(d, message):
    z = hash_to_int(message)
    while True:
        k = rng.randint(1, n - 1)           # fresh random k every time
        x1, y1 = scalar_mult(k, G)          # R = k*G
        r = x1 % n
        if r == 0:
            continue                        # bad k, try again
        s = pow(k, -1, n) * (z + r * d) % n
        if s == 0:
            continue                        # bad k, try again
        return (r, s)


# --------------------------------------------------------------
# verify : uses only the PUBLIC key Q
# --------------------------------------------------------------
def verify(Q, message, signature):
    r, s = signature
    if not (1 <= r < n and 1 <= s < n):     # r and s must be in range
        return False
    z = hash_to_int(message)
    w = pow(s, -1, n)                       # s^-1 mod n
    u1 = z * w % n
    u2 = r * w % n
    X = point_add(scalar_mult(u1, G), scalar_mult(u2, Q))   # u1*G + u2*Q
    if X is None:
        return False
    return X[0] % n == r                    # x-coordinate must give back r


if __name__ == "__main__":
    M = b"Transfer Rs.5000 to Account 1234"
    d, Q = keygen()
    r, s = sign(d, M)
    print("private d :", hex(d)[:20], "...")
    print("public Q  : (", hex(Q[0])[:20], "..., ", hex(Q[1])[:20], "...)")
    print("signature : r =", hex(r)[:20], "...  s =", hex(s)[:20], "...")
    print("verify original :", verify(Q, M, (r, s)))                                  # True
    print("verify tampered :", verify(Q, b"Transfer Rs.9000 to Account 1234", (r, s)))   # False
    d2, Q2 = keygen()
    print("verify wrong key:", verify(Q2, M, (r, s)))                                 # False
